SELECT MAX(appeal_date) AS max_rec, MAX(disallowance_date) AS max_glosa, MAX(invoice_date) AS max_inv FROM curated.totvs_procedure_invoice WHERE system_source = 'totvs-alice' AND provider_class = 'Health Institution' AND invoice_step IN ('1-Digitacao','2-Conferencia','3-Pronta','4-Faturada') AND (institution_type ILIKE '%Clinica%' OR institution_type ILIKE '%Laboratorio%' OR institution_type ILIKE '%Hospital%') AND invoice_date >= '2026-10-01'
